# 41j_mediation_robustness.R
# Robustness checks on the Ch3 mediation model (Prof → Trust → Turbulence)
#
# Four specifications:
#   1. Baseline (contemporaneous, levels) — same as 41i
#   2. First-differenced — removes common time trend
#   3. Lagged IV (prof at t-1) — temporal ordering
#   4. Drop 2020-2022 (COVID + Truss volatility)
#
# OUTPUT: figures/ch3_mediation_robustness_talk.png
#         (coefficient plot: indirect effect + 95% CI across specs)

if (!require("pacman")) install.packages("pacman")
pacman::p_load(ggplot2, readr, tibble, mediation, dplyr)
select <- dplyr::select  # force dplyr::select over MASS::select

.ROOT <- local({
  a <- commandArgs(trailingOnly = FALSE)
  m <- grep("^--file=", a, value = TRUE)
  if (length(m) == 1) normalizePath(file.path(dirname(sub("^--file=", "", m)), ".."))
  else getwd()
})  # portable project root: works via Rscript from anywhere, or falls back to
    # getwd() when sourced interactively (assumes ch3_pipeline_restored/ as cwd)
PROJECT <- .ROOT
OUT     <- file.path(PROJECT, "figures/ch3_mediation_robustness_talk.png")

NAVY <- "#1F3864"; RED <- "#d7191c"; GREY <- "#607D8B"

# ============================================================
# 1. REBUILD PROFESSIONALISATION PC1 (same as 41e-41i)
# ============================================================
norm01 <- function(x) (x - min(x, na.rm=TRUE)) / (max(x, na.rm=TRUE) - min(x, na.rm=TRUE))
YEARS  <- 1979:2025

career_obs <- bind_rows(
  tribble(~year,~pct, 1979,3.0, 1983,4.5, 2010,14.0, 2015,17.0, 2019,21.0),
  tribble(~year,~pct, 1987,5.4, 1992,7.3, 1997,9.5, 2001,10.5, 2005,14.1)
) |> arrange(year)

career_annual <- tibble(year = YEARS) |>
  mutate(obs_yr     = sapply(year, function(y) max(career_obs$year[career_obs$year <= y])),
         career_pct = career_obs$pct[match(obs_yr, career_obs$year)])

spads <- read_csv(file.path(PROJECT, "data/raw/spads_DATA_ENTRY.csv"),
                  show_col_types = FALSE) |> filter(year <= 2025)
spads_annual <- tibble(year = YEARS,
  n_spads = approx(spads$year, spads$n_spads, xout = YEARS, rule = 2)$y)

ipsa  <- read_csv(file.path(PROJECT,"data/processed/ipsa_staffing_annual.csv"),
                  show_col_types=FALSE) |> select(cal_year, staffing_real=mean_staffing_real_2015)
# REPOINTED 7 Sep 2026: Butler & Butler-calibrated real series, see 41m_staffing_calibrate_butler.R
pre10 <- read_csv(file.path(PROJECT,"data/processed/staffing_pre2010_calibrated_butler.csv"),
                  show_col_types=FALSE) |> filter(!is.na(real_2015_mean)) |>
  select(cal_year=year, staffing_real=real_2015_mean)
staffing_obs <- bind_rows(pre10, ipsa) |> arrange(cal_year) |> filter(cal_year <= 2025)
staffing_annual <- tibble(year = YEARS) |>
  mutate(obs_yr        = sapply(year, function(y) max(staffing_obs$cal_year[staffing_obs$cal_year <= y])),
         staffing_real = staffing_obs$staffing_real[match(obs_yr, staffing_obs$cal_year)])

d_prof <- tibble(year = YEARS) |>
  left_join(career_annual   |> select(year, career_pct),    by="year") |>
  left_join(spads_annual    |> select(year, n_spads),        by="year") |>
  left_join(staffing_annual |> select(year, staffing_real),  by="year") |>
  mutate(career_norm   = norm01(career_pct),
         spads_norm    = norm01(n_spads),
         staffing_norm = norm01(staffing_real))

pca_res <- prcomp(d_prof |> select(career_norm, spads_norm, staffing_norm),
                  scale. = TRUE, center = TRUE)
d_prof  <- d_prof |> mutate(prof_pc1 = pca_res$x[, 1])

# ============================================================
# 2. LOAD TRUST AND TURBULENCE
# ============================================================
trust <- read_csv(file.path(PROJECT, "data/processed/trust_extended_1979_2025.csv"),
                  show_col_types = FALSE) |>
  select(year, trust_pct, data_source) |>
  mutate(observed = !grepl("INTERPOLATED", data_source, fixed = TRUE))
# repointed 3 Sep 2026: was reading trust.csv (BSA-only, 1986-2023) — now reads
# the extended 1979-2025 series. Added specs 1b-4b below (BSA-observed years
# only) alongside the original full-sample specs 1-4, since 41i/41g found the
# two diverge sharply on path a (Prof->Trust) — this robustness figure should
# show that divergence, not hide it inside one silently-chosen trust spec.

turb <- read_csv(file.path(PROJECT, "../composite_canonical/canonical_pc1_1979_2025.csv"),
                 show_col_types = FALSE) |>
  select(year, turb_pc1 = PC1_index)
# repointed 2 Sep 2026: was reading a stale local turbulence_pca.csv (2005-2023,
# 5-component pm_churn spec) — now reads the canonical composite (1979-2025,
# 6-component exec_instab spec). See wkbd-composite-stale-canonical memory.
# NOTE: trust_pct itself still only covers 1986-2024 (BSA) — this repoint fixes
# the DV's own truncation but the mediation sample is still capped by trust
# coverage, not by turbulence coverage, until the trust gap is separately closed.

# ============================================================
# 3. BASE MERGE
# ============================================================
d_base <- turb |>
  inner_join(trust, by = "year") |>
  inner_join(d_prof |> select(year, prof_pc1), by = "year") |>
  filter(!is.na(trust_pct), !is.na(turb_pc1), !is.na(prof_pc1))

cat(sprintf("Base dataset: N = %d, years %d-%d\n\n", nrow(d_base), min(d_base$year), max(d_base$year)))

# ============================================================
# 4. FUNCTION TO RUN MEDIATION AND EXTRACT RESULTS
# ============================================================
run_mediation <- function(data, spec_label, treat = "prof_pc1", med = "trust_pct",
                          outcome = "turb_pc1", sims = 5000) {
  data <- data |> filter(!is.na(.data[[treat]]), !is.na(.data[[med]]), !is.na(.data[[outcome]]))
  n <- nrow(data)
  if (n < 8) {
    cat(sprintf("  %s: N = %d — too few, skipped\n", spec_label, n))
    return(NULL)
  }

  fmla_m <- as.formula(paste(med, "~", treat))
  fmla_y <- as.formula(paste(outcome, "~", treat, "+", med))

  eq_m <- lm(fmla_m, data = data)
  eq_y <- lm(fmla_y, data = data)

  set.seed(42)
  med_out <- tryCatch(
    mediate(eq_m, eq_y, treat = treat, mediator = med, sims = sims),
    error = function(e) { cat(sprintf("  %s: mediation error — %s\n", spec_label, e$message)); NULL }
  )
  if (is.null(med_out)) return(NULL)

  # Extract
  a_coef <- coef(eq_m)[treat]
  b_coef <- coef(eq_y)[med]
  cp     <- coef(eq_y)[treat]
  total  <- coef(lm(as.formula(paste(outcome, "~", treat)), data = data))[treat]

  cat(sprintf("  %s: N=%d | c=%.3f | c'=%.3f | a=%.3f | b=%.3f | indirect=%.3f [%.3f, %.3f] p=%.3f\n",
              spec_label, n, total, cp, a_coef, b_coef,
              med_out$d0, med_out$d0.ci[1], med_out$d0.ci[2], med_out$d0.p))

  tibble(
    spec     = spec_label,
    n        = n,
    total    = total,
    direct   = cp,
    a        = a_coef,
    b        = b_coef,
    indirect = med_out$d0,
    lo95     = med_out$d0.ci[1],
    hi95     = med_out$d0.ci[2],
    p        = med_out$d0.p,
    prop_med = med_out$n0
  )
}

# ============================================================
# 5. RUN FOUR SPECIFICATIONS
# ============================================================
cat("=== Running mediation robustness ===\n")

# Spec 1: Baseline (contemporaneous, levels)
r1 <- run_mediation(d_base, "1. Baseline (levels)")

# Spec 2: First-differenced
d_diff <- d_base |>
  arrange(year) |>
  mutate(d_prof  = prof_pc1  - lag(prof_pc1),
         d_trust = trust_pct - lag(trust_pct),
         d_turb  = turb_pc1  - lag(turb_pc1)) |>
  filter(!is.na(d_prof))

r2 <- run_mediation(d_diff, "2. First-differenced",
                    treat = "d_prof", med = "d_trust", outcome = "d_turb")

# Spec 3: Lagged IV (prof at t-1)
d_lag <- d_base |>
  arrange(year) |>
  mutate(prof_lag1 = lag(prof_pc1)) |>
  filter(!is.na(prof_lag1))

r3 <- run_mediation(d_lag, "3. Lagged IV (t-1)",
                    treat = "prof_lag1")

# Spec 4: Drop 2020-2022
d_trim <- d_base |> filter(!(year %in% 2020:2022))

r4 <- run_mediation(d_trim, "4. Excl. 2020-2022")

# Spec 5: Lagged IV (prof at t-2) — PJ asked whether any spec tests a 2-year
# IV lag; previously only t-1 (spec 3) existed
d_lag2 <- d_base |>
  arrange(year) |>
  mutate(prof_lag2 = lag(prof_pc1, 2)) |>
  filter(!is.na(prof_lag2))

r5 <- run_mediation(d_lag2, "5. Lagged IV (t-2)",
                    treat = "prof_lag2")

# Spec 6: Lagged mediator->DV (b-path) — trust at year t predicting
# turbulence at year t+1, professionalisation and trust still contemporaneous
# with each other (a-path unchanged). Previously NOTHING lagged the b-path —
# every prior spec only ever lagged professionalisation (the a-path/IV).
d_blag <- d_base |>
  arrange(year) |>
  mutate(turb_lead1 = lead(turb_pc1)) |>
  filter(!is.na(turb_lead1))

r6 <- run_mediation(d_blag, "6. Lagged b-path (trust_t -> turb_t+1)",
                    outcome = "turb_lead1")

# ============================================================
# REPEAT SPECS 1-6 ON BSA-OBSERVED YEARS ONLY
# ============================================================
d_base_obs <- d_base |> filter(observed)
cat(sprintf("\nBSA-observed-only base dataset: N = %d, years %d-%d\n\n",
            nrow(d_base_obs), min(d_base_obs$year), max(d_base_obs$year)))

r1b <- run_mediation(d_base_obs, "1b. Baseline (levels) — BSA-observed only")

d_diff_obs <- d_base_obs |>
  arrange(year) |>
  mutate(d_prof  = prof_pc1  - lag(prof_pc1),
         d_trust = trust_pct - lag(trust_pct),
         d_turb  = turb_pc1  - lag(turb_pc1)) |>
  filter(!is.na(d_prof))
r2b <- run_mediation(d_diff_obs, "2b. First-differenced — BSA-observed only",
                     treat = "d_prof", med = "d_trust", outcome = "d_turb")

d_lag_obs <- d_base_obs |>
  arrange(year) |>
  mutate(prof_lag1 = lag(prof_pc1)) |>
  filter(!is.na(prof_lag1))
r3b <- run_mediation(d_lag_obs, "3b. Lagged IV (t-1) — BSA-observed only",
                     treat = "prof_lag1")

d_trim_obs <- d_base_obs |> filter(!(year %in% 2020:2022))
r4b <- run_mediation(d_trim_obs, "4b. Excl. 2020-2022 — BSA-observed only")

d_lag2_obs <- d_base_obs |>
  arrange(year) |>
  mutate(prof_lag2 = lag(prof_pc1, 2)) |>
  filter(!is.na(prof_lag2))
r5b <- run_mediation(d_lag2_obs, "5b. Lagged IV (t-2) — BSA-observed only",
                     treat = "prof_lag2")

d_blag_obs <- d_base_obs |>
  arrange(year) |>
  mutate(turb_lead1 = lead(turb_pc1)) |>
  filter(!is.na(turb_lead1))
r6b <- run_mediation(d_blag_obs, "6b. Lagged b-path (trust_t -> turb_t+1) — BSA-observed only",
                     outcome = "turb_lead1")

# ============================================================
# 6. COMBINE AND PLOT
# ============================================================
results <- bind_rows(r1, r2, r3, r4, r5, r6, r1b, r2b, r3b, r4b, r5b, r6b) |>
  mutate(
    spec  = factor(spec, levels = rev(unique(spec))),
    sig   = p < 0.05,
    label = sprintf("N=%d  p=%.3f", n, p)
  )

cat("\n=== Summary ===\n")
print(results |> select(spec, n, indirect, lo95, hi95, p, prop_med))

p_rob <- ggplot(results, aes(x = indirect, y = spec, colour = sig)) +
  geom_vline(xintercept = 0, linetype = "dashed", colour = GREY, linewidth = 0.5) +
  geom_errorbar(aes(xmin = lo95, xmax = hi95), width = 0.2, linewidth = 0.8) +
  geom_point(size = 3.5) +
  geom_text(aes(label = label), size = 2.8, hjust = -0.1, colour = "grey30") +
  scale_colour_manual(
    values = c("TRUE" = RED, "FALSE" = GREY),
    labels = c("TRUE" = "p < 0.05", "FALSE" = "p \u2265 0.05"),
    name   = NULL
  ) +
  scale_x_continuous(expand = expansion(mult = c(0.05, 0.45))) +
  labs(
    title    = "Mediation robustness: indirect effect of professionalisation via trust",
    subtitle = paste0(
      "Indirect effect (a \u00d7 b) + 95% CI from Imai et al. (2010) simulation (5,000 draws).\n",
      "Specs 1-6: full trust sample (incl. TrustGov/Ipsos-calibrated years). ",
      "Specs 1b-6b: BSA-observed years only.\n",
      "1/1b: contemporaneous levels. 2/2b: first-differenced (removes trend). ",
      "3/3b: IV lagged 1yr. 4/4b: drops COVID/Truss years.\n",
      "5/5b: IV lagged 2yr. 6/6b: b-path lagged (trust_t predicts turbulence_t+1, a-path stays contemporaneous).\n",
      "Dashed line = zero. Red = significant at 5%. Neither trust spec is designated headline yet \u2014 PJ to confirm."
    ),
    caption  = paste0(
      "IV: professionalisation PC1 (career politicians, SPADs, staffing). ",
      "Mediator: political trust % (BSA observed + TrustGov/Ipsos-calibrated, see 41k/41l). ",
      "DV: turbulence PC1 (6-component canonical composite, 1979-2025)."
    ),
    x = "Indirect effect (a \u00d7 b)",
    y = NULL
  ) +
  theme_bw(base_size = 12) +
  theme(
    plot.title       = element_text(face = "bold", colour = NAVY, size = 12),
    plot.subtitle    = element_text(colour = GREY, size = 8, lineheight = 1.3),
    plot.caption     = element_text(colour = GREY, size = 7.5),
    panel.grid.minor = element_blank(),
    legend.position  = "top"
  )

ggsave(OUT, p_rob, width = 10, height = 12, dpi = 300)
cat("\nRobustness figure saved:", OUT, "\n")
